INSERT INTO public.support_quick_replies VALUES ('59ded6e5-1823-44d5-b01b-2336391836e2', 'Looking into it', 'Hello {name}, thank you for telling us. We are looking into it now and will get back to you shortly.', NULL, '2026-10-14 13:12:18.848654+00');
INSERT INTO public.support_quick_replies VALUES ('b6da1821-ac3e-4a96-a870-3dd41b5dbfb0', 'Try clock-in again', 'Hello {name}, please close Xtend completely, make sure Location, Camera and Notifications are allowed, stand outside in the open for a minute, then try to clock in again. Tell us here if it still does not work.', NULL, '2026-10-14 13:12:18.848654+00');
INSERT INTO public.support_quick_replies VALUES ('9893976b-b015-4693-b99c-113bd7ea0b3a', 'Fixed, try again', 'Hello {name}, this has been fixed on our side. Please try again now and let us know if anything is still wrong.', NULL, '2026-10-14 13:12:18.848654+00');
INSERT INTO public.support_quick_replies VALUES ('b3c8d89e-29d6-435f-9f52-d963b73d899c', 'Store change done', 'Hello {name}, your store has been updated. Close and open Xtend again to see it.', NULL, '2026-10-14 13:12:18.848654+00');
INSERT INTO public.support_quick_replies VALUES ('1bf1614f-74e6-4ed6-bcc0-3b98355567dc', 'Call your supervisor', 'Hello {name}, please call your supervisor about this today so they can sort it out with you directly.', NULL, '2026-10-14 13:12:18.848654+00');
INSERT INTO public.xm_policy_versions VALUES ('6a4b1347-810c-4764-93de-f6bd603b040e', 'How X Metrics scores your work', 'X Metrics gives every merchandiser and marketer a monthly score from 0 to 100, from what you send from your stores. The weights and bands below are set by the office.
